$('region').value=savedGet('kma-region')||'yeoju';if(!REGIONS.some(r=>r.id===$('region').value))$('region').value='yeoju';$('period').onchange=render;$('region').onchange=()=>{savedSet('kma-region',$('region').value);render()};$('target').onchange=history;$('demo').onclick=()=>{mode='demo';data=demo();render();tab('report')};$('real').onclick=()=>{mode='real';data=base;render();tab('report')};$('import').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>12000000)throw Error('파일 크기는 12MB 이하여야 합니다.');const next=validate(JSON.parse(await f.text()));base=next;data=base;mode='real';imported=true;const saved=savedSet('kma-import',JSON.stringify(base));$('importMessage').textContent=saved?'가져오기 완료. 이 기기에 저장했습니다.':'분석할 수 있지만 저장 공간이 부족하여 재방문 시 유지되지 않습니다.';render();tab('report')}catch(err){$('importMessage').textContent='가져오기 실패: '+err.message}finally{e.target.value=''}};$('clear').onclick=()=>{try{localStorage.removeItem('kma-import')}catch{}base=serverData;data=base;mode='real';imported=false;$('importMessage').textContent='가져온 자료를 지웠습니다.';render()};$('export').onclick=()=>{const blob=new Blob([JSON.stringify(viewData(),null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=mode==='demo'?'가상자료_실제성적아님.json':'기상청성적표_자료.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
